from pathlib import Path
from playwright.sync_api import sync_playwright
import json
out=Path(__file__).resolve().parent;out.mkdir(exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':488,'height':850});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:8773/YaguaTool/');page.wait_for_timeout(250);report={'tips':[],'selection':[],'responsive':[]}
 for section in ['text','motion','tools']:
  page.evaluate('(s)=>YaguaPanel.navigate(s)',section);page.wait_for_timeout(150)
  for w in [260,340,488,1100]:
   page.set_viewport_size({'width':w,'height':850});page.wait_for_timeout(450)
   chips=page.locator('.chip.on');
   if chips.count():
    box=chips.first.evaluate('e=>{let a=e.getBoundingClientRect(),m=e.querySelector(".yagua-selection-mark").getBoundingClientRect(),t=e.querySelector(".chip-name")?.getBoundingClientRect();return {a:{x:a.x,y:a.y,r:a.right,b:a.bottom},m:{x:m.x,y:m.y,r:m.right,b:m.bottom},textRight:t?.right}}');assert box['m']['r']<=box['a']['r'] and box['m']['y']>=box['a']['y'];assert box['textRight'] is None or box['m']['x']>=box['textRight'];report['selection'].append({'section':section,'width':w,**box})
   target=page.locator('#page .chip[data-tip]:visible').first if section in ['text','motion'] else page.locator('#page button[data-tip]').filter(has_text='Solid').first;target.scroll_into_view_if_needed();target.hover();page.wait_for_timeout(120);tip=page.locator('#yagua-tooltip');assert tip.is_visible();box=tip.bounding_box();assert box['x']>=11 and box['x']+box['width']<=w-11 and box['y']>=11 and box['y']+box['height']<=850-11;report['tips'].append({'section':section,'width':w,'box':box,'font':tip.evaluate('e=>getComputedStyle(e).fontSize')});page.mouse.move(0,0);page.wait_for_timeout(30);assert not tip.is_visible();target.evaluate('e=>e.blur()');target.focus();assert tip.is_visible();page.keyboard.press('Escape');assert not tip.is_visible()
   v=page.evaluate('({doc:document.documentElement.scrollWidth,w:innerWidth,scroll:document.getElementById("page").scrollWidth,client:document.getElementById("page").clientWidth})');assert v['doc']<=v['w']+1 and v['scroll']<=v['client']+1;report['responsive'].append({'section':section,'width':w,**v})
  page.set_viewport_size({'width':488,'height':850});page.wait_for_timeout(450);target=page.locator('#page .chip[data-tip]:visible').first if section in ['text','motion'] else page.locator('#page button[data-tip]').filter(has_text='Solid').first;target.scroll_into_view_if_needed();target.hover();page.screenshot(path=str(out/(section+'-tooltip.png')))
 page.evaluate('YaguaPanel.navigate("text")');heading=page.get_by_role('heading',name='Zoom tipográfico · opcional');heading.scroll_into_view_if_needed();report['zoom_gap']=heading.evaluate('e=>e.nextElementSibling.getBoundingClientRect().top-e.getBoundingClientRect().bottom');assert report['zoom_gap']>=10;page.screenshot(path=str(out/'Zoom.png'))
 family=page.locator('.preset-family').first;family.scroll_into_view_if_needed();family.hover();report['halo']=family.evaluate('e=>{let a=e.getBoundingClientRect(),r=e.querySelector(":scope>.yagua-halo-ring").getBoundingClientRect();return {width:a.width,ringWidth:r.width,height:a.height,ringHeight:r.height,oldPseudo:getComputedStyle(e,"::before").content}}');assert abs(report['halo']['width']-report['halo']['ringWidth'])<=2 and abs(report['halo']['height']-report['halo']['ringHeight'])<=2;page.screenshot(path=str(out/'Family-halo.png'))
 page.evaluate('YaguaPanel.navigate("text",null,"lab","pack-apple-style-pack-slide")');page.wait_for_timeout(150);check=page.locator('#showAllControls');check.scroll_into_view_if_needed();report['checkbox']=check.evaluate('e=>({w:e.offsetWidth,h:e.offsetHeight,appearance:getComputedStyle(e).appearance,checked:e.checked})');assert report['checkbox']['w']==16 and report['checkbox']['h']==16;before=check.is_checked();check.click();assert check.is_checked()!=before;check.press('Space');assert check.is_checked()==before;page.screenshot(path=str(out/'Checkbox.png'));report['errors']=errors;assert not errors;b.close()
(out/'POLISH.json').write_text(json.dumps(report,indent=2));print('PASS',len(report['tips']),'tooltip positions,',len(report['responsive']),'layouts, halo, checkbox, selected marks, zoom gap',report['zoom_gap'])
